def test_object_z():
    o = Object(1, 2, z=3)
    assert o.x == 1
    assert o.y == 2
    assert o.z == 3
    pos = o.get_position()
    assert pos.shape == (3,), f"expected 3D, got {pos.shape}"
    assert pos[2] == 3
    print("  PASS Object.__init__ stores z")


def test_object_relative_to_all_angles():
    o = Object(1, 0, z=0.5, roll=0.1, pitch=0.2, yaw=0.3)
    o.relative_to(10, 20, robot_z=2, robot_roll=0.05, robot_pitch=0.15, robot_yaw=math.pi / 2)
    # yaw rotation: (x=1, y=0) rotated 90° -> (-0, 1) ≈ (0, 1), then + (10, 20)
    assert abs(o.x - 10) < 1e-9, f"x={o.x}"
    assert abs(o.y - 21) < 1e-9, f"y={o.y}"
    assert abs(o.z - 2.5) < 1e-9, f"z={o.z}"
    assert abs(o.roll - 0.15) < 1e-9, f"roll={o.roll}"
    assert abs(o.pitch - 0.35) < 1e-9, f"pitch={o.pitch}"
    assert abs(o.yaw - (0.3 + math.pi / 2) % (2 * math.pi)) < 1e-9, f"yaw={o.yaw}"
    print("  PASS Object.relative_to transforms z, roll, pitch, yaw")


