def test_pnp_to_robot_coordinates():
    cfg = _make_cfg()
    cam_cfg = iSpyCameraConfig({
        "name": "test", "source": 99,
        "fps_cap": 1000, "yaw": 45, "pitch": 0, "height": 1.0,
        "x": 0.5, "y": 0.3, "z": 0.2,
        "subsystem": "test",
        "calibration": {"distance": 1.0, "game_piece_size": 1.0, "size": 100, "fov": 90},
    })
    camera = ObjectDetectionCamera(cam_cfg, cfg)

    tvec = (1.0, 0.5, 3.0)
    pt = camera._pnp_to_robot_coordinates(tvec)
    assert len(pt) == 3, f"expected 3D, got {len(pt)}"
    # yaw=45°: cos=sin≈0.7071
    c = math.cos(math.radians(45))
    s = math.sin(math.radians(45))
    scale = 0.0254
    x_rot = 3.0 * c + (-1.0) * s
    y_rot = 3.0 * s - (-1.0) * c
    expected_x = (x_rot + 0.5) * scale
    expected_y = (y_rot + 0.3) * scale
    expected_z = (-0.5 + 0.2) * scale
    assert abs(pt[0] - expected_x) < 1e-6, f"x={pt[0]} != {expected_x}"
    assert abs(pt[1] - expected_y) < 1e-6
    assert abs(pt[2] - expected_z) < 1e-6
    print("  PASS _pnp_to_robot_coordinates with yaw+offsets")


