def main():
    tests = [
        ("Object z", test_object_z),
        ("Object relative_to all angles", test_object_relative_to_all_angles),
        ("Object get_position 3D", test_object_get_position_3d),
        ("Object get_position_normally 3D", test_object_get_position_normally_3d),
        ("Box PnP path", test_box_pnp_path),
        ("Box bbox-only path", test_box_bbox_only_path),
        ("Tracker EMA z+angles", test_tracker_ema_z_and_angles),
        ("Tracker angle wrapping", test_tracker_angle_wrapping),
        ("Results.plot translation", test_results_plot_shows_translation),
        ("FuelStruct z", test_fuel_struct_z),
        ("has_rotation", test_has_rotation),
        ("_pnp_to_robot_coordinates", test_pnp_to_robot_coordinates),
        ("Object.__str__ shows Z", test_object_str_shows_z),
        ("Camera config default z", test_camera_config_default_has_z),
        ("Camera loads camera_z", test_camera_loads_camera_z),
    ]

    passed = 0
    failed = 0
    for name, fn in tests:
        print(f"Test: {name}")
        try:
            fn()
            passed += 1
            print(f"  OK\n")
        except Exception as e:
            failed += 1
            print(f"  FAIL: {e}\n")

    print(f"=" * 40)
    print(f"Total: {passed + failed}  Passed: {passed}  Failed: {failed}")
    return 0 if failed == 0 else 1


if __name__ == "__main__":
    sys.exit(main())
